begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,auth,pg_catalog;
select no_plan();
\ir helpers/reminder_521_fixtures.sql
update private.learner_profile_access_control set rollout_state='signed-in-public' where singleton;
select ok(not has_function_privilege('service_role','public.claim_due_typed_reminder_dry_runs(timestamptz,integer,integer,integer)','execute'),'mutating typed preview RPC is retired');
select ok(not has_function_privilege('service_role','public.complete_typed_reminder_dry_run(uuid,timestamptz)','execute'),'mutating typed preview completion is retired');
select ok(has_function_privilege('service_role','public.evaluate_reminder_shadow(timestamptz)','execute'),'service can evaluate a read-only preview');
select ok(not has_function_privilege('authenticated','public.evaluate_reminder_shadow(timestamptz)','execute'),'browser cannot inspect other owners eligibility');
select hasnt_column('private','reminder_deliveries','email','ledger omits recipient email');
select is((select count(*) from private.reminder_discovery_channels),7::bigint,'only reviewed launch catalog is used');
select ok((select relrowsecurity from pg_class where oid='private.reminder_discovery_channels'::regclass),'private catalog has RLS');
select ok(not has_table_privilege('service_role','private.reminder_discovery_channels','select'),'catalog is accessed only through service capabilities');
select pg_temp.email_fixture('52110000-0000-4000-8000-000000000001','Asia/Taipei','2026-10-26',9,10);
select pg_temp.email_fixture('52110000-0000-4000-8000-000000000002','Asia/Taipei','2026-10-26',10,10);
select public.refresh_reminder_eligibility_snapshots(10,'2026-10-26T11:00:00Z');
select is((select candidate_count from public.evaluate_reminder_shadow('2026-10-26T11:05:00Z') where email_type='streak'),1::bigint,'nine XP permits streak reminder');
select is((select candidate_count from public.evaluate_reminder_shadow('2026-10-26T11:05:00Z') where email_type='discovery'),1::bigint,'ten XP chooses discovery from catalog with zero peers');
select is((select count(*) from private.reminder_deliveries),0::bigint,'preview materializes no real occurrence');
select is((select count(*) from private.reminder_capacity_admissions),0::bigint,'preview consumes no daily admission token');
select is((select count(*) from private.reminder_quota_reservations),0::bigint,'preview consumes no quota');
select * from public.evaluate_reminder_shadow('2026-10-26T11:05:00Z');
select is((select count(*) from private.reminder_deliveries),0::bigint,'repeated preview still has no ledger side effects');
update public.reminder_preferences set streak_enrollment_version=null,discovery_enrollment_version=null;
select is((select count(*) from public.evaluate_reminder_shadow('2026-10-26T11:05:00Z')),0::bigint,'checked preferences alone never enroll');
select * from finish();
rollback;
